"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["93304"],{95911(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.fato_candidato.regra_padrao_malformada","status":422,"titulo":"A lista de regras, uma regra ou uma condi\xe7\xe3o veio nula"},"descricao":{"codigo":"uniplus.configuracao.fato_candidato.regra_padrao_malformada","requisitos":["UNI-REQ-0075"],"oQueAconteceu":["O administrador substituiu as regras padr\xe3o de um fato derivado por regra (`PUT /api/configuracao/admin/fatos-candidato/{id}/regras-padrao`), e o corpo traz uma regra `null` na lista `regras`, ou uma condi\xe7\xe3o `null` dentro das cl\xe1usulas de `quando` de uma regra. A regra padr\xe3o \xe9 uma estrutura fechada, com as condi\xe7\xf5es `quando` e o valor que contribui (UNI-REQ-0075), e a API n\xe3o a completa em sil\xeancio.","A recusa vem na lista `errors` da resposta, com `field` igual ao \xedndice da regra, como `regras[0]`. A mensagem \xe9 a de regra ou condi\xe7\xe3o nula. Esta confer\xeancia vem antes da busca do fato ([fato do candidato n\xe3o encontrado](/erros/uniplus.configuracao.fato_candidato.nao_encontrado)), de modo que o corpo malformado recebe esta recusa mesmo quando o `{id}` n\xe3o existe. Nada \xe9 gravado.","O corpo sem a lista `regras`, ou com a lista nula, \xe9 recusado antes, como erro de requisi\xe7\xe3o (400): s\xf3 a lista vazia, `[]`, remove as regras."],"comoResolver":["Retire os `null` do corpo: cada regra \xe9 um objeto com `quando`, a lista de cl\xe1usulas, cada uma a lista de condi\xe7\xf5es, e com `contribui`, o c\xf3digo do valor do derivado categ\xf3rico, que o derivado booleano n\xe3o informa. Exemplo de uma regra de derivado categ\xf3rico, com um fato fict\xedcio:","```json\\n{\\n  \\"regras\\": [\\n    {\\n      \\"contribui\\": \\"EJA\\",\\n      \\"quando\\": [[{ \\"fato\\": \\"CURSOU_SUPLETIVO\\", \\"operador\\": \\"IGUAL\\", \\"valor\\": true }]]\\n    }\\n  ]\\n}\\n```"],"ondeAparece":["Defini\xe7\xe3o das regras padr\xe3o de um fato derivado por regra"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Fato candidato"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"0258f07cac6c9b7f9d70290a4b0385549eb99572"}}')}}]);